#[test]
fn real_windows_conpty_quit_restores_terminal_visual_state() {
    let executable = lbe_binary();

    assert!(
        executable.exists(),
        "expected LBE binary at {}",
        executable.display()
    );

    let pty_system = NativePtySystem::default();

    let pair = pty_system
        .openpty(PtySize {
            rows: 40,
            cols: 120,
            pixel_width: 0,
            pixel_height: 0,
        })
        .expect("open Windows ConPTY");

    let cmd = CommandBuilder::new(executable);

    let mut child = pair
        .slave
        .spawn_command(cmd)
        .expect("spawn LBE inside Windows ConPTY");

    drop(pair.slave);

    let mut reader = pair
        .master
        .try_clone_reader()
        .expect("clone ConPTY reader");

    let (tx, rx) = mpsc::channel();

    let reader_thread = thread::spawn(move || {
        let mut output = Vec::new();
        let _ = reader.read_to_end(&mut output);
        let _ = tx.send(output);
    });

    let mut writer = pair
        .master
        .take_writer()
        .expect("take ConPTY writer");

    // Bounded startup allowance for terminal initialization and first draw.
    thread::sleep(Duration::from_millis(250));

    writer.write_all(b"q").expect("send q");
    writer.flush().expect("flush q");
    drop(writer);

    let status = child.wait().expect("wait for LBE process");

    assert!(
        status.success(),
        "LBE process exited unsuccessfully: {status:?}"
    );

    drop(pair.master);

    let output = rx
        .recv_timeout(Duration::from_secs(3))
        .expect("receive captured ConPTY output");

    reader_thread.join().expect("join ConPTY reader");

    let output = String::from_utf8_lossy(&output);

    let alt_enter = "\u{1b}[?1049h";
    let alt_leave = "\u{1b}[?1049l";
    let cursor_hide = "\u{1b}[?25l";
    let cursor_show = "\u{1b}[?25h";

    assert!(
        output.contains(alt_enter),
        "LBE never entered alternate screen; output length={}",
        output.len()
    );

    assert!(
        output.contains(cursor_hide),
        "LBE never hid cursor; output length={}",
        output.len()
    );

    assert!(
        output.contains(alt_leave),
        "LBE did not leave alternate screen"
    );

    assert!(
        output.contains(cursor_show),
        "LBE did not restore cursor visibility"
    );

    assert!(
        output.rfind(alt_leave).unwrap() > output.rfind(alt_enter).unwrap(),
        "alternate-screen leave must occur after enter"
    );

    assert!(
        output.rfind(cursor_show).unwrap() > output.rfind(cursor_hide).unwrap(),
        "cursor show must occur after cursor hide"
    );
}
